import{_ as t,o as a,c as l,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const p=JSON.parse('{"title":"Classical","description":"","frontmatter":{},"headers":[],"relativePath":"demos/CLASSICAL.md","filePath":"demos/CLASSICAL.md"}'),o={name:"demos/CLASSICAL.md"};function r(s,e,i,c,h,d){return a(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="classical" tabindex="-1">Classical <a class="header-anchor" href="#classical" aria-label="Permalink to &quot;Classical&quot;">​</a></h1><p>The demo songs in the classical style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#bolero_swell">Swell</a>: <code>16_bolero_swell.yml</code></li><li><a href="#pachelbel">Patterns Only</a>: <code>02_pachelbel.yml</code></li><li><a href="#voice_leading">Voice Leading</a>: <code>05_voice_leading.yml</code></li></ul><p><a id="bolero_swell"></a></p><h2 id="swell-16-bolero-swell-yml" tabindex="-1">Swell: <code>16_bolero_swell.yml</code> <a class="header-anchor" href="#swell-16-bolero-swell-yml" aria-label="Permalink to &quot;Swell: `16_bolero_swell.yml`&quot;">​</a></h2><p>An original piece in three in the manner of Ravel&#39;s Bolero: one tune and one snare rhythm, nine scenes of one unbroken crescendo from soft to full force, climbing evenly in loudness, without one velocity changed in a pattern. Each scene&#39;s Swell starts where the one before ended, the first three scenes keep the same instruments so that only the loudness climbs, and in the last the timpani run through a Swell generator that accents every downbeat. Use velocity-sensitive instruments to hear it.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/16_bolero_swell.yml" target="_blank" rel="noreferrer"><code>examples/learning/16_bolero_swell.yml</code></a> · C major · 72 BPM · 3:00 · 9 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="pachelbel"></a></p><h2 id="patterns-only-02-pachelbel-yml" tabindex="-1">Patterns Only: <code>02_pachelbel.yml</code> <a class="header-anchor" href="#patterns-only-02-pachelbel-yml" aria-label="Permalink to &quot;Patterns Only: `02_pachelbel.yml`&quot;">​</a></h2><p>The opening of Pachelbel&#39;s Canon in D for three violins and a cello, using nothing but patterns and scenes, the way you might copy a score in. Because it&#39;s a canon, the violins share the same patterns, each a scene behind the one before.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/02_pachelbel.yml" target="_blank" rel="noreferrer"><code>examples/learning/02_pachelbel.yml</code></a> · D major · 44 BPM · 1:19 · 7 scenes · 4 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="voice_leading"></a></p><h2 id="voice-leading-05-voice-leading-yml" tabindex="-1">Voice Leading: <code>05_voice_leading.yml</code> <a class="header-anchor" href="#voice-leading-05-voice-leading-yml" aria-label="Permalink to &quot;Voice Leading: `05_voice_leading.yml`&quot;">​</a></h2><p>Block chords on the piano over a bass in D major, three progressions each played three ways, back to back: in root position, every chord jumping up from its root; inverted by hand with the chord editor&#39;s Inv. row; and through the Voice leading generator, which plays each chord in the inversion and octave nearest the chord before. The last scene keeps the root in the bass.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/05_voice_leading.yml" target="_blank" rel="noreferrer"><code>examples/learning/05_voice_leading.yml</code></a> · D major · 96 BPM · 3:00 · 9 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',18)])])}const b=t(o,[["render",r]]);export{p as __pageData,b as default};
